{
  "items": [
    {
      "title": "Crime in the Modern City (Kriminalität in der modernen Stadt) – Duisburg 2002",
      "url_or_doi": "https://doi.org/10.4232/1.14595",
      "justification": "Highly relevant longitudinal research dataset examining adolescent psychology, delinquency, social behavior, attitudes toward crime, and social control in Duisburg. Data collection began in 2002 with school students. The study investigates psychological and social factors associated with juvenile delinquency, including family influences, peer relationships, and behavioral development. Archived by GESIS."
    },
    {
      "title": "Crime in the Modern City – Duisburg 2003",
      "url_or_doi": "https://doi.org/10.4232/1.14596",
      "justification": "The 2003 wave of a longitudinal study following adolescents in Duisburg. Relevant to developmental psychology, behavioral psychology, social attitudes, and adolescent risk-taking. Particularly useful for studying changes in psychological and behavioral characteristics between 2002 and 2003."
    },
    {
      "title": "Crime in the Modern City – Duisburg 2004",
      "url_or_doi": "https://doi.org/10.4232/1.14597",
      "justification": "A 2004 dataset from the Duisburg longitudinal study investigating adolescent delinquency, socialization, and behavioral development. Relevant psychological research topics include attitudes toward deviance, parenting styles, peer influences, and behavioral patterns. Suitable for longitudinal analysis of adolescent psychology during the 2000s."
    },
    {
      "title": "Duisburg Birth Cohort Study – Psychological and Neurodevelopmental Data",
      "url_or_doi": "https://atlaslongitudinaldatasets.ac.uk/datasets/duisburg-birth-cohort-study",
      "justification": "Highly relevant to developmental psychology and child cognitive development in Duisburg. Beginning in 2000, this longitudinal birth cohort followed more than 200 mother-child pairs from southern Duisburg. The study collected psychological, cognitive, neurodevelopmental, and mental health measurements, including attention and developmental assessments. Particularly useful for investigating relationships between early environmental exposures and children's psychological development. Data access requires contacting the research team."
    },
    {
      "title": "Duisburg Citizen Survey – Spring 2000 (Duisburger Bürgerumfrage Frühjahr 2000)",
      "url_or_doi": "https://doi.org/10.4232/1.3468",
      "justification": "Population survey conducted in Duisburg between February and March 2000, covering residents aged 18–75. Relevant to social psychology through its examination of residents' perceptions, social attitudes, and evaluations of urban living conditions. Useful for studying subjective experiences and community attitudes at the beginning of the 2000s. Available through the GESIS Data Archive."
    },
    {
      "title": "Duisburg Citizen Survey – Autumn 2000 (Duisburger Bürgerumfrage Herbst 2000)",
      "url_or_doi": "https://doi.org/10.4232/1.3469",
      "justification": "Survey conducted between October and November 2000 among Duisburg residents aged 18–75. Potentially useful for social and community psychology, particularly research into subjective evaluations of local conditions, social perceptions, and public attitudes. Provides a second observation point in 2000 for studying changes in residents' attitudes."
    },
    {
      "title": "Duisburg Citizen Survey – Autumn 2005, German Population",
      "url_or_doi": "https://doi.org/10.4232/1.4516",
      "justification": "A 2005 survey of German residents aged 18–75 in Duisburg. Relevant to social psychology and the psychological dimensions of urban life, including perceptions of the local environment and social attitudes. Useful for examining relationships between demographic characteristics, subjective evaluations of living conditions, and community perceptions."
    },
    {
      "title": "Duisburg Citizen Survey – Autumn 2005, Foreign Population",
      "url_or_doi": "https://doi.org/10.4232/1.4523",
      "justification": "A 2005 dataset specifically covering foreign residents of Duisburg aged 18–75. Contains 571 observations and 212 variables. Particularly relevant to cross-cultural psychology, migration psychology, and social integration research. Can be compared with the corresponding German-population survey to investigate differences in social perceptions and experiences between population groups."
    },
    {
      "title": "Crime in the Modern City – Duisburg 2009",
      "url_or_doi": "https://www.selectdataset.com/dataset/74d1bd50775a8d8e25f7a4dc2ed30dac/crime-in-the-modern-city-2009",
      "justification": "A dataset from the 2009 wave of the longitudinal Duisburg study that began in 2002. Relevant to developmental psychology, adolescent behavioral development, aggression, substance use, and social influences on delinquency. Includes self-reported behavioral information and measures related to criminal activity. Especially valuable for examining psychological and behavioral changes across adolescence during the 2000s."
    }
  ]
}
